solution:
def first_n_primes(n):
    def primes():
        found = []
        candidate = 2
        while True:
            if all(candidate % p != 0 for p in found if p * p <= candidate):
                found.append(candidate)
                yield candidate
            candidate += 1

    gen = primes()
    return [next(gen) for _ in range(n)]

